type EstadoPedido = "pendiente" | "enviado" | "entregado";

function obtenerMensaje(estado: EstadoPedido): string {
  switch (estado) {
    case "pendiente":
      return "Tu pedido está pendiente.";
    case "enviado":
      return "Tu pedido está en camino.";
    case "entregado":
      return "Tu pedido fue entregado.";
  }
}

